<?php
namespace App\Services;use App\Models\{ComparisonRun,FeedbackResponse,Survey};use Illuminate\Validation\ValidationException;
class HistoricalComparisonService{
 public function compare(Survey $baseline,Survey $followup,int $userId):ComparisonRun{$checks=$this->compatibility($baseline,$followup);$comparable=collect($checks)->every(fn($v)=>$v===true);$limitations=array_keys(array_filter($checks,fn($v)=>$v!==true));if(!$comparable)throw ValidationException::withMessages(['comparison'=>'Surveys are not comparable: '.implode(', ',$limitations)]);$a=$this->metrics($baseline);$b=$this->metrics($followup);$changes=[];foreach(['coverage_percent','median_rssi_dbm','median_download_mbps','median_latency_ms','median_packet_loss_percent','average_satisfaction','complaint_count'] as $key)$changes[$key]=($a[$key]!==null&&$b[$key]!==null)?round($b[$key]-$a[$key],3):null;return ComparisonRun::updateOrCreate(['baseline_survey_id'=>$baseline->id,'followup_survey_id'=>$followup->id,'calculation_version'=>'1.0'],['created_by'=>$userId,'status'=>'completed','is_comparable'=>true,'compatibility_checks'=>$checks,'baseline_metrics'=>$a,'followup_metrics'=>$b,'changes'=>$changes,'limitations'=>[],'calculated_at'=>now()]);}
 public function compatibility(Survey $a,Survey $b):array{return['different_surveys'=>$a->id!==$b->id,'same_floor'=>$a->floor_id===$b->floor_id,'same_floor_plan_version'=>$a->floor_plan_id===$b->floor_plan_id,'same_survey_area'=>$a->survey_area_id===$b->survey_area_id,'baseline_has_measurements'=>$a->points()->whereHas('measurements',fn($q)=>$q->where('is_simulated',false))->exists(),'followup_has_measurements'=>$b->points()->whereHas('measurements',fn($q)=>$q->where('is_simulated',false))->exists()];}
 private function metrics(Survey $s):array{$m=$s->points()->with(['measurements'=>fn($q)=>$q->where('is_simulated',false)])->get()->flatMap->measurements;$median=function($c){$c=$c->filter(fn($v)=>$v!==null)->map(fn($v)=>(float)$v)->sort()->values();if($c->isEmpty())return null;$n=$c->count();return round($n%2?$c[intdiv($n,2)]:($c[$n/2-1]+$c[$n/2])/2,3);};$heat=$s->heatmaps()->where('status','completed')->latest('generated_at')->first();$from=$m->min('captured_at')??$s->created_at;$to=$m->max('captured_at')??$s->updated_at;$feedback=FeedbackResponse::where('floor_id',$s->floor_id)->when($s->survey_area_id,fn($q)=>$q->where('survey_area_id',$s->survey_area_id))->whereBetween('experienced_at',[$from,$to]);return['coverage_percent'=>$heat?->coverage_percent!==null?(float)$heat->coverage_percent:null,'median_rssi_dbm'=>$median($m->pluck('rssi_dbm')),'median_download_mbps'=>$median($m->pluck('download_mbps')),'median_latency_ms'=>$median($m->pluck('latency_ms')),'median_packet_loss_percent'=>$median($m->pluck('packet_loss_percent')),'measurement_count'=>$m->count(),'average_satisfaction'=>$feedback->exists()?round((float)$feedback->avg('overall_satisfaction'),3):null,'complaint_count'=>$feedback->count(),'period_start'=>(string)$from,'period_end'=>(string)$to];}}
